-- ---------------------------------------------------------------------------
-- POSTFLIGHT: coherence (any violation rolls the whole batch back)
-- ---------------------------------------------------------------------------
do $post016$
declare
  v_rest integer; v_places integer; v_unver integer; v_coords integer;
  v_nolink integer; v_nosrc integer; v_hotel integer; v_other integer;
begin
  select count(*) into v_rest from public.restaurants where source = 'tptm-b16';
  if v_rest <> 8 then
    raise exception 'POSTFLIGHT FAIL: expected 8 batch-016 restaurant rows, found %.', v_rest;
  end if;
  select count(*) into v_places from public.places where source = 'tptm-b16';
  if v_places <> 10 then
    raise exception 'POSTFLIGHT FAIL: expected 10 batch-016 place rows, found %.', v_places;
  end if;

  select count(*) into v_unver from public.restaurants where source = 'tptm-b16' and verification_status <> 'unverified';
  v_unver := v_unver + (select count(*) from public.places where source = 'tptm-b16' and verification_status <> 'unverified');
  if v_unver <> 0 then
    raise exception 'POSTFLIGHT FAIL: % rows are not unverified — an import never self-verifies.', v_unver;
  end if;

  select count(*) into v_coords from public.restaurants where source = 'tptm-b16' and (latitude is not null or longitude is not null);
  v_coords := v_coords + (select count(*) from public.places where source = 'tptm-b16' and latitude is not null);
  if v_coords <> 0 then
    raise exception 'POSTFLIGHT FAIL: expected ZERO coordinate rows (published OSM coords stay in evidence), found %.', v_coords;
  end if;

  select count(*) into v_nolink from public.places where source = 'tptm-b16' and destination_id is null;
  if v_nolink <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing destination linkage.', v_nolink;
  end if;

  select count(*) into v_nosrc from public.places where source = 'tptm-b16' and (source_url is null or source_url = '');
  if v_nosrc <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing source_url.', v_nosrc;
  end if;

  select count(*) filter (where place_type = 'hotel') into v_hotel from public.places where source = 'tptm-b16';
  select count(*) filter (where place_type = 'other') into v_other from public.places where source = 'tptm-b16';
  if v_hotel <> 9 or v_other <> 1 then
    raise exception 'POSTFLIGHT FAIL: place_type distribution drifted (hotel=% other=%; expected 9/1).', v_hotel, v_other;
  end if;
  raise notice 'POSTFLIGHT OK: 18 rows verified (8 restaurants + 10 places; hotel 9, other 1).';
end
